#!/usr/bin/env python3
"""Compile validated native home layout tokens. No device-side JSON parsing."""
import argparse,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
LAYERS=['background','artwork','details','shelves','focus','navigation','status']
LIMITS={'rail_width':(40,120),'menu_width':(160,400),'menu_item_height':(40,96),'menu_top':(48,160),
'inset':(8,64),'top':(48,160),'gap':(0,64),'context_percent':(25,55),'card_width':(96,320),'card_height':(80,300),
'card_gap':(4,64),'row_gap':(8,80),'focus_percent':(100,120),'animation_ms':(0,800),
'description_width_percent':(25,100),'description_lines':(1,8),'games_heading_visible':(0,1),'caption_background_alpha':(0,255),'caption_padding':(0,16),'title_margin_bottom':(0,256),'metadata_margin_bottom':(0,256),'description_margin_bottom':(0,256),'shelf_margin_bottom':(0,256),'card_margin_bottom':(0,256),'nav_margin_bottom':(0,256),'brand_margin_bottom':(0,256),'battery_margin_bottom':(0,256),'clock_margin_bottom':(0,256),'badge_margin_bottom':(0,256),'info_margin_bottom':(0,256),'games_margin_bottom':(0,256),'consoles_margin_bottom':(0,256),'title_margin_top':(0,256),'metadata_margin_top':(0,256),'description_margin_top':(0,256),'shelf_margin_top':(0,256),'card_margin_top':(0,256),'nav_margin_top':(0,256),'brand_margin_top':(0,256),'battery_margin_top':(0,256),'clock_margin_top':(0,256),'badge_margin_top':(0,256),'info_margin_top':(0,256),'games_margin_top':(0,256),'consoles_margin_top':(0,256),'badge_text_height':(14,27),'metadata_height':(14,42),'description_height':(14,42),'shelf_text_height':(14,42),'card_text_height':(14,36),'nav_text_height':(14,28),'brand_text_height':(14,27),'title_width_percent':(25,100),'title_height':(14,84),'title_anchor_last_line':(0,1),'info_width_percent':(30,80),'mask_text_shade_percent':(0,100),'artwork_width_numerator':(1,100),'artwork_width_denominator':(1,100),'artwork_height_percent':(25,100),'mask_clear_left_percent':(0,90),'mask_vertical_inset_percent':(0,40)}
def compile_layout(path):
 d=json.loads(path.read_text());assert set(d)=={'version','layers','layout'} and d['version']==1
 assert set(d['layers'])==set(LAYERS) and set(d['layout'])==set(LIMITS)
 for k,v in d['layers'].items():assert type(v) is int and 1<=v<=10
 assert [d['layers'][k] for k in LAYERS]==sorted(set(d['layers'].values()))
 assert d['layers']['status']==10
 for k,(low,high) in LIMITS.items():assert type(d['layout'][k]) is int and low<=d['layout'][k]<=high
 assert d['layout']['rail_width']<d['layout']['menu_width']
 assert d['layout']['artwork_width_numerator']<=d['layout']['artwork_width_denominator']
 fields={k+'_layer':d['layers'][k] for k in LAYERS};fields.update(d['layout'])
 return '// SPDX-License-Identifier: GPL-2.0-only\n// Generated by design/compile-home.py.\n#include "home-layout.h"\nconst struct mp_home_layout mp_home_layout_default = {\n'+''.join(f'    .{k} = {v},\n' for k,v in fields.items())+'};\n'
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--input',type=Path,default=ROOT/'design/themes/minpocket-default/home-layout.json');p.add_argument('--output',type=Path,default=ROOT/'native/home-layout-default.c');p.add_argument('--check',action='store_true');a=p.parse_args()
 try:
  result=compile_layout(a.input)
  if a.check:
   if a.output.read_text()!=result:p.error('Generated home layout is out of date')
  else:a.output.write_text(result)
 except (ValueError,AssertionError,KeyError,TypeError) as e:p.error(f'Invalid native home layout: {e}')
